const menuButton=document.querySelector('.menu-toggle');const nav=document.querySelector('#site-nav');menuButton.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open));menuButton.textContent=open?'Close':'Menu'});nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.textContent='Menu'}));const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));document.querySelector('#year').textContent=new Date().getFullYear();document.querySelectorAll('[data-placeholder-link]').forEach(link=>link.addEventListener('click',event=>{if(link.getAttribute('href')==='#')event.preventDefault()}));const copyEmailButton=document.querySelector('.copy-email');copyEmailButton?.addEventListener('click',async()=>{const email=copyEmailButton.dataset.email;try{await navigator.clipboard.writeText(email);copyEmailButton.textContent='Copied!'}catch{const input=document.createElement('textarea');input.value=email;document.body.appendChild(input);input.select();document.execCommand('copy');input.remove();copyEmailButton.textContent='Copied!'}setTimeout(()=>{copyEmailButton.textContent='Copy email'},1800)});
